import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  /** Render prop receives (error, reset) so custom UIs can wire up retry. */
  fallback?: ReactNode | ((error: Error, reset: () => void) => ReactNode);
  /** Called after componentDidCatch — plug in an external logger here. */
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  componentStack: string | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, componentStack: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    const stack = info.componentStack ?? null;
    console.error("[ErrorBoundary] Uncaught render error", {
      name: error.name,
      message: error.message,
      componentStack: stack,
      error,
    });
    this.setState({ componentStack: stack });
    this.props.onError?.(error, info);
  }

  reset = (): void => {
    this.setState({ error: null, componentStack: null });
  };

  render(): ReactNode {
    const { error, componentStack } = this.state;

    if (!error) return this.props.children;

    const { fallback } = this.props;

    if (fallback !== undefined) {
      return typeof fallback === "function" ? fallback(error, this.reset) : fallback;
    }

    return (
      <div
        role="alert"
        style={{
          padding: "1rem",
          border: "1px solid red",
          borderRadius: "4px",
          fontFamily: "sans-serif",
        }}
      >
        <h2 style={{ margin: "0 0 0.5rem" }}>Something went wrong</h2>
        <pre
          style={{
            margin: "0 0 0.75rem",
            padding: "0.5rem",
            background: "#fff0f0",
            color: "red",
            borderRadius: "2px",
            whiteSpace: "pre-wrap",
            wordBreak: "break-word",
          }}
        >
          {error.message}
        </pre>
        {componentStack && (
          <details style={{ marginBottom: "0.75rem" }}>
            <summary style={{ cursor: "pointer", color: "#666" }}>
              Component stack
            </summary>
            <pre
              style={{
                margin: "0.25rem 0 0",
                fontSize: "0.8em",
                color: "#666",
                whiteSpace: "pre-wrap",
                wordBreak: "break-word",
              }}
            >
              {componentStack}
            </pre>
          </details>
        )}
        <button onClick={this.reset}>Try Again</button>
      </div>
    );
  }
}
